export const row=(n,patch={})=>({contractId:id(n),registrationId:id(1000+n),legajo:String(5000+n),name:'PERSONA SINTÉTICA '+String(n).padStart(3,'0'),dni:'99999990',cuil:'20999999906',sexCode:null,birthDate:'1990-01-01',startDate:'2026-09-01',endDate:null,status:'active',jurisdictionCode:n%2?'42':'55',agreement:'Convenio QA',category:'Clase QA',organization:'Sector QA',sector:'Repartición QA',jobTitle:null,legalReference:'Resolución sintética QA',registeredAt:'2026-09-30T12:00:00Z',...patch});
export function roster(count=57,patch={}){const rows=Array.from({length:count},(_,i)=>row(i+1));return{version:'native-roster.v1',origin:'MUNICONTROL',complete:true,today:'2026-10-01',queriedAt:'2026-10-01T12:00:00Z',scope:{tenantId:TENANT,membershipId:MEMBER,bindingId:id(900),companyId:7},filters:{search:'',status:'all',jurisdiction:'',organization:'',sector:'',agreement:''},total:count,people:count,counts:{active:count,pending_start:0,inactive:0,state_error:0},facets:{organization:['Sector QA'],sector:['Repartición QA'],agreement:['Convenio QA']},rows,snapshot:'a'.repeat(64),...patch};}
